mapper.select:
SELECT COALESCE(SUM(attempt.estimated_cost),0)
FROM dms_message_delivery_attempt attempt JOIN dms_message_delivery_task task ON task.id=attempt.task_id AND task.tenant_id=attempt.tenant_id
WHERE attempt.tenant_id=#{tenantId} AND attempt.state IN ('PREPARED','SUBMITTED','UNKNOWN','ACCEPTED','DELIVERED') AND attempt.create_time >= #{fromTime}

    AND task.event_type=#{scopeKey}
    AND task.channel=#{scopeKey}
